import{c as a,Q as t,j as r,m as o}from"./chunks/framework.BXc4yaFE.js";const g=JSON.parse('{"title":"Token-Budget-Aware LLM Reasoning","description":"","frontmatter":{"url":"https://arxiv.org/abs/2412.18547","title":"Token-Budget-Aware LLM Reasoning","archived_date":"2026-07-17T00:00:00.000Z","arxiv_id":2412.18547,"authors":["Tingxu Han","Zhenting Wang","Chunrong Fang","Shiyu Zhao","Shiqing Ma","Zhenyu Chen"],"domains":["cs.CL","cs.AI","cs.LG"],"html":"https://arxiv.org/html/2412.18547v1","pdf_path":"pdfs/2412.18547.pdf","published_date":"2024-12-24T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2024-12-24-token-budget-aware-llm-reasoning-2412-18547.md","filePath":"research/papers/2024-12-24-token-budget-aware-llm-reasoning-2412-18547.md","lastUpdated":1785909234000}'),n={name:"research/papers/2024-12-24-token-budget-aware-llm-reasoning-2412-18547.md"};function s(i,e,l,h,d,c){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="token-budget-aware-llm-reasoning" tabindex="-1">Token-Budget-Aware LLM Reasoning <a class="header-anchor" href="#token-budget-aware-llm-reasoning" aria-label="Permalink to &quot;Token-Budget-Aware LLM Reasoning&quot;">​</a></h1><p><strong>Authors</strong>: Tingxu Han, Zhenting Wang, Chunrong Fang, Shiyu Zhao, Shiqing Ma, Zhenyu Chen <strong>Published</strong>: December 24, 2024 <strong>Source</strong>: <a href="https://arxiv.org/abs/2412.18547" target="_blank" rel="noreferrer">https://arxiv.org/abs/2412.18547</a> · <a href="https://arxiv.org/html/2412.18547v1" target="_blank" rel="noreferrer">HTML</a><strong>arXiv ID</strong>: 2412.18547 <strong>Categories</strong>: cs.CL, cs.AI, cs.LG <strong>PDF</strong>: <a href="https://arxiv.org/abs/2412.18547" target="_blank" rel="noreferrer">research/papers/pdfs/2412.18547.pdf</a></p><hr><h2 id="abstract-quoted" tabindex="-1">Abstract (quoted) <a class="header-anchor" href="#abstract-quoted" aria-label="Permalink to &quot;Abstract (quoted)&quot;">​</a></h2><blockquote><p>Reasoning is critical for large language models (LLMs) to excel in a wide range of tasks. While methods like Chain-of-Thought (CoT) reasoning enhance LLM performance by decomposing problems into intermediate steps, they also incur significant overhead in token usage, leading to increased costs. We find that the reasoning process of current LLMs is unnecessarily lengthy and it can be compressed by including a reasonable token budget in the prompt, but the choice of token budget plays a crucial role in the actual compression effectiveness. We then propose a token-budget-aware LLM reasoning framework that dynamically adjusts the number of reasoning tokens based on the reasoning complexity of each problem. Experiments show that our method effectively reduces token costs in CoT reasoning with only a slight performance reduction, offering a practical solution to balance efficiency and accuracy in LLM reasoning.</p></blockquote><hr><h2 id="結構化摘要" tabindex="-1">結構化摘要 <a class="header-anchor" href="#結構化摘要" aria-label="Permalink to &quot;結構化摘要&quot;">​</a></h2><h3 id="核心貢獻" tabindex="-1">核心貢獻 <a class="header-anchor" href="#核心貢獻" aria-label="Permalink to &quot;核心貢獻&quot;">​</a></h3><ul><li>實證 CoT 推理過程「不必要地冗長」：在 prompt 中給合理 token budget 即可壓縮，且 budget 數值選擇是壓縮成效關鍵</li><li>提出 TALE（token-budget-aware）框架：依每題推理複雜度動態估算並注入 budget</li></ul><h3 id="關鍵結果" tabindex="-1">關鍵結果 <a class="header-anchor" href="#關鍵結果" aria-label="Permalink to &quot;關鍵結果&quot;">​</a></h3><ul><li>顯著降低 CoT token 成本、僅輕微效能下降；具體百分比未取得（abstract 未含）</li></ul><h3 id="限制" tabindex="-1">限制 <a class="header-anchor" href="#限制" aria-label="Permalink to &quot;限制&quot;">​</a></h3><ul><li>budget 估算本身需要一次額外判斷；估太低會截斷關鍵推理步驟</li><li>2024 年模型世代的結果，對現代原生 reasoning 模型（有 effort 參數）的遷移性未知</li></ul><hr><h2 id="workspace-關聯-評估-非既成結論" tabindex="-1">Workspace 關聯（評估，非既成結論） <a class="header-anchor" href="#workspace-關聯-評估-非既成結論" aria-label="Permalink to &quot;Workspace 關聯（評估，非既成結論）&quot;">​</a></h2><ul><li>支持 <code>.claude/skills/output-compress</code> 的檔位上限與 model-profiles「effort 先於 model」原則：token budget 是與檔位獨立的第一調節軸。</li><li>「budget 選擇決定壓縮成效」印證分級（lite/full/ultra）而非單一開關的設計；budget 由確定性規則指定、非 LLM 自選，契合「判斷 vs 決定」公理。</li></ul>',16)])])}const p=a(n,[["render",s]]);export{g as __pageData,p as default};
